"""Regenerate PINHOLES.md from the tables (so the document cannot drift from the data). usage: pinhole_md.py
Inputs: tables/latent_connection_sweep.csv, tables/pinholes_summary.csv, tables/pinholes_top_candidates.csv, ext/national_county2020.txt (county names)."""
import sys, time, pandas as pd
import os as _os; sys.path.insert(0, _os.path.dirname(_os.path.abspath(__file__)))
from common import *
SW = pd.read_csv(f"{OUT}/latent_connection_sweep.csv"); SM = pd.read_csv(f"{OUT}/pinholes_summary.csv"); TP = pd.read_csv(f"{OUT}/pinholes_top_candidates.csv", dtype={"tract": str})
cn = pd.read_csv(f"{REPO_ROOT}/ext/national_county2020.txt", sep="|", dtype=str); cn["code"] = cn.STATEFP + cn.COUNTYFP; CN = dict(zip(cn.code, cn.COUNTYNAME + ", " + cn.STATE))
NAME = {"northern-ca": "Northern California", "eastern-ok": "Eastern Oklahoma", "maricopa-az": "Maricopa AZ (+Pima/Pinal/Coconino)", "south-central-tx": "South-Central Texas", "eastern-wa": "Eastern Washington"}
L = []
L.append(f"# PINHOLES.md - appendix (not promoted after verification): single-link exposure that hinges on a short unconnected stretch   (generated by egress/pinhole_md.py)\n")
L.append("STATUS OF THE EVIDENCE: quantified on Overture only; calibrated on two open documentation sets (Hays, Tehama: repairs never improve agreement, CALIBRATION.md) but NOT verified against any independent open road inventory, so pinholes are an appendix candidate list, not a finding. Every row below is a CANDIDATE for verification, not a claim that a road is missing.\n")
L.append("## Definition\nBaseline: S30 = dwellings whose path to the arterial network crosses a bridge (single link) serving >= 30 dwellings. Repair at radius r (egress/sens_nearmiss2.py): every dead-end tip (degree-1 node, not a sink) is joined to the nearest road piece it does not already touch within r metres.\n"
         "Per baseline single-link cluster (top-level bridge): `relieved_dw` = its dwellings that stop being S30 after the 50 m repair; `min_gap_m` = the shortest external repair distance that touches the cluster (tip inside -> piece outside, or the reverse). Code: egress/pinhole_list.py, pinhole_summary.py; tables/pinholes_<region>_r50.csv.\n")
L.append("## 1. How much single-link exposure depends on short connections (relative cut of the S30 share; tables/latent_connection_sweep.csv)")
L.append("| region | S30 baseline | cut at <=25 m | <=50 m | <=100 m | <=250 m (upper bound) | median repair distance at 100 m |\n|---|---|---|---|---|---|---|")
for _, r in SW.iterrows():
    L.append(f"| {NAME[r.region]} | {100*r.S30_base:.1f} % | {r.cut_25m_pct:.1f} % | {r.cut_50m_pct:.1f} % | {r.cut_100m_pct:.1f} % | {r.cut_250m_pct:.1f} % | {r.median_repair_dist_100m:.0f} m |")
L.append(f"\nRanges over the five regions: <=25 m {SW.cut_25m_pct.min():.0f}-{SW.cut_25m_pct.max():.0f} %, <=50 m {SW.cut_50m_pct.min():.0f}-{SW.cut_50m_pct.max():.0f} %, <=100 m {SW.cut_100m_pct.min():.0f}-{SW.cut_100m_pct.max():.0f} %, <=250 m {SW.cut_250m_pct.min():.0f}-{SW.cut_250m_pct.max():.0f} % -> at least {100-SW.cut_250m_pct.max():.0f}-{100-SW.cut_250m_pct.min():.0f} % of the exposure survives even the most generous reconnection.\n")
L.append("## 2. Clusters of >= 100 dwellings whose single-link status disappears for a short gap (tables/pinholes_summary.csv)")
L.append("| region | clusters >= 100 dw | >=50 % relieved with gap <= 10 m | <= 25 m | <= 50 m |\n|---|---|---|---|---|")
for _, r in SM.iterrows():
    nm = NAME.get(r.region, r.region)
    L.append(f"| {nm} | {int(r.clusters_ge100):,} ({r.dw_in_clusters:,.0f} dwellings) | {int(r['clusters_relieved50pct_gap<=10m'])} | {int(r['clusters_relieved50pct_gap<=25m'])} | {int(r['clusters_relieved50pct_gap<=50m'])} |")
last = SM.iloc[-1]
L.append(f"\nDwellings relieved in clusters (>= 100 dw) whose shortest gap is <= 10 / 25 / 50 m: {last['dw_relieved_gap<=10m']:,.0f} / {last['dw_relieved_gap<=25m']:,.0f} / {last['dw_relieved_gap<=50m']:,.0f} (pooled; sums relieved dwellings of all >= 100-dwelling clusters with such a gap, without the 50 % condition).\n")
L.append(f"## 3. Top candidates (>= 100-dwelling cluster, >= 50 % of its dwellings relieved, shortest gap <= 25 m; {len(TP)} in total, all with lon/lat in tables/pinholes_top_candidates.csv). Three per region, ranked by dwellings relieved")
L.append("| Region | Place (Overture locality) | Road | Tract | County | Dwellings behind link | Relieved | Gap |\n|---|---|---|---|---|---|---|---|")
for reg in ["northern-ca", "eastern-ok", "maricopa-az", "south-central-tx", "eastern-wa"]:
    for _, r in TP[TP.region == reg].sort_values("relieved_dw", ascending=False).head(3).iterrows():
        rn = r.rname if isinstance(r.rname, str) else "(unnamed road)"
        L.append(f"| {NAME[reg].split(' (')[0]} | {r.place} | {rn} | {r.tract} | {CN.get(r.tract[:5], '')} | {r.load_dw:,.0f} | {r.relieved_dw:,.0f} | {r.min_gap_m:.1f} m |")
L.append("\nNote: gaps of 4-10 m are more plausibly digitising defects than real dead ends, but gates, walls or private emergency accesses are also possible - unknown.\n")
CAL = open(f"{OUT}/validation_hays_repair_summary.txt").read().strip().split("\n")
L.append("## 4. Independent calibration of the repairs (Hays County study; validation/validate_hays_repair.py, tables/validation_hays_repair*.csv)")
L.append("```\n" + "\n".join(CAL) + "\n```")
L.append("Reading: repairs of <= 25 m change nothing in the independent check; 50 m costs one documented single-exit flag; >= 100 m erases 6-7 of the 17 documented single-exit flags with no gain on false positives -> the 100-250 m numbers in section 1 are an over-estimate and only the <= 50 m candidates are credible. The one documented multi-exit false positive (Goldenwood, 3 published exits) is NOT a short-gap case: it stays at 0.62 single-route up to 100 m.\n")
L.append("## 5. Caveats that bound any claim\n* r > 25 m is an upper bound: private drives, fences, terrain and gated emergency accesses are not excluded.\n* Tips are matched to the nearest piece of the SAME scored-class graph (no service/track roads), so some 'gaps' may be service roads the graph deliberately ignores.\n"
         "* Not yet compared with any reference network or imagery. Nearest related forum post: 35033 (Texas low-water-crossing closure with a 20 m near-miss filter).\n* The scorecard cannot register any of this: its road component counts kilometres of arterial road only.\n")
L.append("## 6. Reproduce\ncd .../egress; `sh run_nm2.sh` (sweep; ~15 min for 5 regions, Texas ~8 min); `for R in northern-ca eastern-ok maricopa-az south-central-tx eastern-wa; do $PY pinhole_list.py $R 50; done`; `$PY latent_sweep_table.py`; `$PY pinhole_summary.py`; `$PY pinhole_md.py`.\n")
open(f"{REPO_ROOT}/PINHOLES.md", "w").write("\n".join(L)); print("wrote PINHOLES.md", sum(len(x.split()) for x in L), "words")
